def min_cover(s,t):
    if not t:return ''
    need={}
    for c in t:need[c]=need.get(c,0)+1
    have={};formed=0;left=0;best=(len(s)+1,0,0)
    for right,c in enumerate(s):
        have[c]=have.get(c,0)+1
        if c in need and have[c]==need[c]:formed+=1
        while formed==len(need):
            if right-left+1<best[0]:best=(right-left+1,left,right+1)
            d=s[left];have[d]-=1
            if d in need and have[d]<need[d]:formed-=1
            left+=1
    return '' if best[0]>len(s) else s[best[1]:best[2]]

